import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_section_2_weighted_pool_and_empty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event(str(i), 1, False) for i in range(3)], "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (9, 9)])
def test_section_3_window(days, expected):
    assert flags_in_window [email protected] ([2, 3, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_section_4_parser_values_whitespace_and_skips():
    lines = ["", "  \t", "  # comment,with,commas", "  a  ,  -2 , 1  ",
             "b, 3, 0", "c,4,  "]
    assert parse_transcript_log(iter(lines)) == [event("a", -2, True),
                                                 event("b", 3, False),
                                                 event("c", 4, None)]


@pytest.mark.parametrize("line", ["too,few", "too,many,fields,here", "a,nope,1", "a,1,yes"])
def test_section_4_parser_reports_input_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log([" ", "# comment", "valid,1,1", line])


def test_section_5_last_duplicate_wins_and_sort_by_day_then_id():
    events = [event("b", 1, True), event("a", 3, True), event("c", 2, None),
              event("b", 2, False), event("a", 2, False)]
    assert dedupe_transcripts(events) == [events[4], events[3], events[2]]
    assert dedupe_transcripts([]) == []


def test_section_6_counts_inclusive_range_and_gaps():
    events = [event("a", 1, True), event("b", 2, True), event("c", 2, True),
              event("d", 3, None), event("e", 4, False), event("f", 5, True)]
    assert daily_flag_counts(events, 2, 4) == [2, 0, 0]
    assert daily_flag_counts(events, 2, 2) == [2]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 2) == []


def test_section_7_summary_pooled_rounded_calendar_window_and_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 4, True), event("c", 4, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 20) == {"rate": 0.667, "recent": 2, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_section_8_ranking_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("a", 1, True)], "empty": [],
              "b": [event("b", 1, False)], "a": [event("c", 1, True)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 9) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 5) == []


def test_section_9_sorted_mapping_including_empty_groups():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert flag_rate_by_group({}) == {}


